\label{thm:main}
There exist $K,C,c\in(0,\infty)$, depending only on $p,d$, such that,
for every $x\in\mathbb Z^d\setminus\{0\}$,
\begin{equation}\label{eq:main}
 \mathbb P_p(0\leftrightarrow x,\ K\|x\|<|C_0|<\infty)
 \le C\exp\left\{-\xi_p(x)-c\|x\|^{\frac{d-1}{2d}}\right\}.
\end{equation}

\label{lem:ld}
For each fixed $A<\infty$, there are $K,C,c>0$, independent of $\ell$,
such that for $n\ge1$ and $1\le N\le An$,
\begin{align*}
 \mathbb P_{\mu_\ell}(W_N>Kn)&\le C e^{-cn^\beta},\\
 \mathbb E_{\mu_\ell}[W_N\mathbf1_{\ W_N>Kn}]&\le Cn e^{-cn^\beta}.
\end{align*}

\label{lem:deco}
For $z\in D$ and every nonnegative function $f$ of $C_z^D$,
\begin{equation}\label{eq:extraction_locale}
 \mathbb E_p^D[(1-p)^{b_D(C_z^D)}f(C_z^D)]
 =\mathbb E_p[f(C_z)\,\mathbf1_{\{C_z\subset D\}}].
\end{equation}
In particular,
\begin{equation}\label{eq:local-energy}
 \mathbb E_p^D[(1-p)^{b_D(C_z^D)}\,\mathbf1_{\{
             \max_{y\in C_z^D}\xi_p(y-z)\ge K-a\}}]
 \le cK^de^{-K}.
\end{equation}

\label{lem:tree-size}
For every $\nu>0$ and $\varepsilon>0$, choose $\eta>0$ sufficiently small and $K$
sufficiently large. For all sufficiently large $n=\|x\|$,
\begin{equation}\label{eq:tree-size}
 \mathbb P_p\!\left(E_x(M),N(\mathfrak T)\ge(1+\nu)\xi_p(x)/K\right)
 \le Ce^{-(1+\nu/2)\xi_p(x)},
\end{equation}
and 
\begin{equation}\label{eq:branches-small}
 \mathbb P_p\!\left(E_x(M),N(\mathfrak B)\ge
                         \varepsilon\xi_p(x)/K\right)
 \le Ce^{-\xi_p(x)-c_\varepsilon n}.
\end{equation}

\label{prop:surcharge}
For every $\varepsilon>0$, choose $\eta$ small and then $K$ large.
For large enough $n$, uniformly in $t\in\partial\mathsf K_p$,
\begin{equation}\label{eq:surcharge}
 \mathbb P_p(E_x(M),\mathfrak s_t(\mathfrak t)+KN(\mathfrak B)\ge\varepsilon n)
 \le e^{-t\cdot x-\varepsilon n/2}.
\end{equation}

\label{lem:blocked}
For a constant $c_\delta$,
\begin{equation}\label{eq:blocked-deterministic}
 \#_\delta^{\mathrm{blocked}}(\mathfrak T)\le c_\delta N(\mathfrak B).
\end{equation}
For every $\varepsilon>0$ and suitable $\eta,K$,
\[
 \mathbb P_p(E_x(M),\#_\delta^{\mathrm{blocked}}(\mathfrak T)\ge\varepsilon N(\mathfrak t))\le Ce^{-\xi_p(x)-cn}.
\]

\label{thm:tree-cones}
For every $\varepsilon>0$ and $0<\delta<1/3$, small enough $\eta$ and big enough $K$ give
\[
 \mathbb P_p(E_x(M),\#_\delta^{\mathrm{cone}}(\mathfrak T)\le(1-\varepsilon)N(\mathfrak t))\le Ce^{-\xi_p(x)-cn}
\]
whenever $\mathfrak s_t(x)\le a_0n$, for a sufficiently small $a_0>0$.
Moreover, the number of trunk vertices which are either marked or
blocked is at most
\begin{equation}\label{eq:tree-cones}
 c_\delta\bigl(K^{-1}\mathfrak s_t(\mathfrak t)+N(\mathfrak B)\bigr).
\end{equation}

\label{prop:cones}\label{lemma:few_conepoints}
There exist $a_0,\rho,c,C>0$ such that, if $\mathfrak s_t(x)\le a_0\|x\|$,
\begin{align}
 \mathbb P_p(E_x(M),\#_\delta^{\mathrm{cone}}(C_0;0,x)\le\rho\|x\|)
 &\le Ce^{-\xi_p(x)-c\|x\|},\label{eq:cones-thin}\\
 \mathbb P_p(x\in C_0,\ |C_0|<\infty,\
                  \#_\delta^{\mathrm{cone}}(C_0;0,x)\le\rho\|x\|)
 &\le Ce^{-\xi_p(x)-c\|x\|^\beta}.
\end{align}
The constants are uniform in $t\in\partial\mathsf K_p$.

\label{proposition:tilded}

For $t\in\mathsf K_p$ sufficiently close to $t_0$, uniformly in $t,y$,
\begin{equation}\label{eq:tilted-tails}
 \mathsf p_t(y)+\rho_{\mathrm b,t}(y)+\rho_{\mathrm f,t}(y)
 \le Ce^{-c\|y\|^\beta}.
\end{equation}
For $t\in\partial\mathsf K_p$ in this neighbourhood,
\begin{equation}
 H(t):=\sum_y\mathsf p_t(y)=1.
\end{equation}

\label{prop:drift}
For $x\ne0$ and $t\in\partial\mathsf K_p$ sufficiently close to $t_0$ with $t\cdot x=\xi_p(x)$, there exists \(c>0\) such that
\[\mathbb E_{t,0}[X_1]=c\cdot\dfrac{x}{\|x\|}\]

\label{lemma:TLL}
Consider a random walk \(S_n=\sum_{i=1}^n X_i\), with law $\mathbb P_0$, expectation $\mathbb E_0$ and $S_0=0$, where \(X_i\in\mathbb{Z}^d\) are i.i.d and \(\mathbb E_0(\|X_1\|^l)<\infty\) for every integer \(l\ge1\). Assume that \(\mathbb E_0(X_1)=cs\) with \(c>0\) and \(s\in\mathbb{S}^{d-1}\) and that the covariance matrix of \(X_1\) is non-degenerate. Assume also that the walk is aperiodic. Then, as $k\to\infty$ with $ks\in\mathbb Z^d$, there exists \(C>0\) :
\[\sum_{N\geq 1}\mathbb P_0(S_N=ks)=\dfrac{C}{k^{(d-1)/2}}(1+o_k(1)).\]
